begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
grant usage on schema extensions to connect_privacy_worker; -- test-only pgTAP, rolled back
create function pg_temp.state(q text) returns text language plpgsql as $$begin execute q;return 'ok';exception when others then return sqlstate;end$$;
select ok(not has_function_privilege('authenticated','public.connect_privacy_finish(uuid,uuid,uuid,uuid[])','execute'),'UI cannot erase');
select ok(not has_function_privilege('service_role','public.connect_privacy_finish(uuid,uuid,uuid,uuid[])','execute'),'Edge cannot erase');
select ok(not has_table_privilege('connect_privacy_worker','public.leads','select'),'worker no lead table scan');
select ok(not has_table_privilege('authenticated','private.privacy_suppressions','select'),'ledger replica hidden');
select ok(not has_table_privilege('authenticated','private.privacy_context','insert'),'cannot spoof trigger capability');
select ok(not exists(select 1 from private.connect_retention_policies where approved or automatic_execution or days is not null),'retention no invented legal periods or automatic execution');
insert into auth.users(id,email) values('a3c00000-0000-4000-8000-000000000001','privacy-a@test.local'),('a3c00000-0000-4000-8000-000000000002','privacy-b@test.local');
insert into public.organizations(id,name,slug) values('b3c00000-0000-4000-8000-000000000001','Privacy test','privacy-sql-test');
insert into public.organization_members(organization_id,user_id,role) values('b3c00000-0000-4000-8000-000000000001','a3c00000-0000-4000-8000-000000000001','organization_admin'),('b3c00000-0000-4000-8000-000000000001','a3c00000-0000-4000-8000-000000000002','organization_admin');
insert into public.projects(id,organization_id,name,slug,public_slug,city,state) values('c3c00000-0000-4000-8000-000000000001','b3c00000-0000-4000-8000-000000000001','Privacy','privacy-sql','privacy-sql','Santos','SP');
insert into public.leads(id,organization_id,project_id,buyer_name,contact_channel,contact_value,source,privacy_notice_version) values('f3c00000-0000-4000-8000-000000000001','b3c00000-0000-4000-8000-000000000001','c3c00000-0000-4000-8000-000000000001','Synthetic only','email','privacy-buyer@example.invalid','public','2026-10-23');
create function pg_temp.case_id() returns uuid language sql security definer as $$select id from public.connect_privacy_requests where lead_id='f3c00000-0000-4000-8000-000000000001' and purpose='erase'$$;
select set_config('request.jwt.claim.sub','a3c00000-0000-4000-8000-000000000001',true);set local role authenticated;
select ok(public.connect_privacy_plan('f3c00000-0000-4000-8000-000000000001','request','SQL-PC3C') ? 'requestId','request');
select is((public.connect_privacy_plan('f3c00000-0000-4000-8000-000000000001','request','SQL-PC3C')->>'requestId')::uuid,pg_temp.case_id(),'duplicate request idempotent');
select is(pg_temp.state($$select public.connect_privacy_plan('f3c00000-0000-4000-8000-000000000001','approve','SQL-PC3C')$$),'42501','cannot approve unverified request');
select ok(public.connect_privacy_plan('f3c00000-0000-4000-8000-000000000001','verify','SQL-PC3C') ? 'requestId','identity process explicitly recorded');
select is(pg_temp.state($$select public.connect_privacy_plan('f3c00000-0000-4000-8000-000000000001','approve','SQL-PC3C')$$),'42501','self approval denied');
reset role;select set_config('request.jwt.claim.sub','a3c00000-0000-4000-8000-000000000002',true);set local role authenticated;
select ok(public.connect_privacy_plan('f3c00000-0000-4000-8000-000000000001','approve','SQL-PC3C') ? 'requestId','independent approval');
reset role;set local role connect_privacy_worker;
select is(pg_temp.state($$select public.connect_privacy_prepare(pg_temp.case_id(),'a3c00000-0000-4000-8000-000000000002')$$),'42501','approver cannot execute');
select is(pg_temp.state($$select public.connect_privacy_prepare(pg_temp.case_id(),'a3c00000-0000-4000-8000-000000000001')$$),'55000','unregistered data cannot be erased even if approved');
reset role;
insert into private.privacy_fixtures values('f3c00000-0000-4000-8000-000000000001');
insert into private.privacy_key values(true,extensions.gen_random_bytes(32)) on conflict do nothing;
update public.leads set version=2 where id='f3c00000-0000-4000-8000-000000000001';
set local role connect_privacy_worker;
select is(pg_temp.state($$select public.connect_privacy_prepare(pg_temp.case_id(),'a3c00000-0000-4000-8000-000000000001')$$),'PT409','stale preview rejected');
reset role;update public.leads set version=1 where id='f3c00000-0000-4000-8000-000000000001';
select set_config('request.jwt.claim.sub','a3c00000-0000-4000-8000-000000000002',true);set local role authenticated;
select ok(public.connect_privacy_plan('f3c00000-0000-4000-8000-000000000001','hold','SQL-PC3C') ? 'requestId','hold recorded');
reset role;set local role connect_privacy_worker;
select is(pg_temp.state($$select public.connect_privacy_prepare(pg_temp.case_id(),'a3c00000-0000-4000-8000-000000000001')$$),'42501','hold prevents even synthetic erasure');
reset role;
insert into public.lead_activities(lead_id,activity_type,detail) values('f3c00000-0000-4000-8000-000000000001','note_added','{"note":"Synthetic PII"}');
select is(pg_temp.state($$delete from public.lead_activities where lead_id='f3c00000-0000-4000-8000-000000000001'$$),'42501','history immutability remains outside scoped transaction');
select is((select count(*) from public.lead_activities where lead_id='f3c00000-0000-4000-8000-000000000001'),1::bigint,'hold preserves history');
select * from finish();rollback;
